import PohAva from '@ui-kit/Ava';
import PohCheckbox from '@ui-kit/Checkbox';

interface IConfirmAddVariantProps {
  provider?: string;
  email?: string;
  avatar?: string;
  name?: string;
  socialPage?: string;
  onChangeEmailUp: (checked: boolean) => void;
  onChangeAvaUp: (checked: boolean) => void;
}

function ConfirmAddVariant({
  provider,
  email,
  avatar,
  onChangeEmailUp,
  onChangeAvaUp,
  name,
  socialPage,
}: IConfirmAddVariantProps) {
  return (
    <div>
      <p>
        Вы успешно вошли в <b>{provider}</b> как <b>{name}</b>
        {socialPage && (
          <span>
            {' '}
            ({/* eslint-disable-next-line react/jsx-no-target-blank */}
            <a href={socialPage} target="_blank">
              страница профиля
            </a>
            )
          </span>
        )}
        .
      </p>
      <p>Подтвердите сохранение варианта входа.</p>
      {(email || avatar) && <p>Мы можем обновить кое-какие данные в профиле:</p>}
      {email && (
        <p>
          <PohCheckbox
            onChange={(checked) => onChangeEmailUp(checked)}
            label={`Обновить email (${email})`}
          />
        </p>
      )}
      {email && (
        <p>
          <PohCheckbox
            onChange={(checked) => onChangeAvaUp(checked)}
            label={
              <>
                Обновить аватар (
                <PohAva src={avatar} width={20} />)
              </>
            }
          />
        </p>
      )}
    </div>
  );
}

export default ConfirmAddVariant;
